void sectionFrameRegression(){
 const std::vector<Frame3> parents{Frame3(),Frame3(Vec3(4,5,6),Vec3(0,-1,0),Vec3(1,0,0)),Frame3(Vec3(3,4,5),Vec3(1,0,0),Vec3(0,1,0)),Frame3(Vec3(2,3,4),normalized(Vec3(1,-2,3)),normalized(Vec3(2,1,0)))};
 for(const auto &frame:parents)for(double angle:{0.,kPi/2,kPi,3*kPi/2,.37,2.18})for(bool reverse:{false,true})for(auto style:{DrawingSectionStyle::Removed,DrawingSectionStyle::Full,DrawingSectionStyle::HalfRight,DrawingSectionStyle::HalfLeft}){
  DrawingSheet s;DrawingView p;p.kind=DrawingViewKind::ProjectedEdges;p.plane=frame;p.scale=2;DrawingView c;c.sectionStyle=style;DrawingViewLayout pl{p.id,"Madre",{50,50},{1}},cl{c.id,"Sezione",{150,80},{1}};
  auto &rel=cl.relation;rel.parentId=p.id;rel.kind=DrawingDerivedKind::Section;rel.label="A";rel.cutStart={3,7};rel.cutEnd=rel.cutStart+20*QPointF(std::cos(angle),std::sin(angle));rel.reverse=reverse;rel.aligned=false;s.drawing.views={p,c};s.views={pl,cl};
  ok(alignDrawingSectionOrientation(s,c.id));ok(synchronizeDrawingViews(s));ok(validateDrawingRelations(s));const auto &child=s.drawing.views[1];
  const auto tangent=std::cos(angle)*frame.xDir()+std::sin(angle)*frame.yDir();const auto local=child.plane.directionToLocal(tangent);
  close(local.x(),std::cos(angle),"ribaltamento conserva componente X della linea sulla madre");close(local.y(),std::sin(angle),"ribaltamento conserva componente Y della linea sulla madre");close(local.z(),0,"linea contenuta nel piano di sezione");
  require(distance(child.plane.zDir(),(reverse?-1:1)*cross(tangent,frame.zDir()))<1e-10,"normale coerente con le frecce");require(distance(child.plane.origin(),frame.toGlobal(Vec3(3,7,0)))<1e-10,"piano passa per il primo punto del taglio");
  close(dot(cross(child.plane.xDir(),child.plane.yDir()),child.plane.zDir()),1,"frame destrorso senza specchiature");
 }
}
